// Turns font files into small JS modules of SVG outlines, so the plugin needs no
// font loading at runtime and can measure text exactly. Only run this when a theme
// needs a new font or character; the generated files are committed.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import opentype from 'opentype.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'com.ulanzi.systemmonitorpro.ulanziPlugin/plugin/render/glyphs');
const EM = 1000;

const range = (from, to) => Array.from({ length: to - from + 1 }, (_, i) => String.fromCodePoint(from + i));

// Labels and notes come in English and Portuguese, so the fonts need accented Latin. Readings are digits and symbols.
const LABEL_CHARS = [
  ...range(0x20, 0x7e),
  ...range(0xc0, 0xff).filter((c) => c !== '×' && c !== '÷'),
  '°', '·', '…', '−', '—', '›', '‹',
];
const FONTS = [
  { id: 'outfit-500', pkg: 'outfit', weight: 500, chars: LABEL_CHARS },
  { id: 'outfit-700', pkg: 'outfit', weight: 700, chars: LABEL_CHARS },
];

function loadSubsets(pkg, weight) {
  const subsets = [];
  for (const subset of ['latin', 'latin-ext']) {
    const file = join(root, `node_modules/@fontsource/${pkg}/files/${pkg}-${subset}-${weight}-normal.woff`);
    if (!existsSync(file)) continue;
    const bytes = readFileSync(file);
    subsets.push(opentype.parse(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength)));
  }
  if (!subsets.length) throw new Error(`no font files for ${pkg} ${weight}`);
  return subsets;
}

// Written by hand because opentype.js's toPathData drops the separator when a small negative
// value rounds to zero ("499 0" becomes "4990"), which tears the outlines.
function pathData(commands) {
  const pair = (x, y) => `${Math.round(x) + 0} ${Math.round(y) + 0}`;
  return commands.map((c) => {
    switch (c.type) {
      case 'M':
      case 'L':
        return `${c.type}${pair(c.x, c.y)}`;
      case 'Q':
        return `Q${pair(c.x1, c.y1)} ${pair(c.x, c.y)}`;
      case 'C':
        return `C${pair(c.x1, c.y1)} ${pair(c.x2, c.y2)} ${pair(c.x, c.y)}`;
      default:
        return 'Z';
    }
  }).join('');
}

mkdirSync(outDir, { recursive: true });

for (const spec of FONTS) {
  const subsets = loadSubsets(spec.pkg, spec.weight);
  const glyphs = {};
  const missing = [];
  for (const char of spec.chars) {
    const font = subsets.find((f) => f.charToGlyphIndex(char) > 0);
    if (!font) {
      missing.push(char);
      continue;
    }
    const glyph = font.charToGlyph(char);
    const advance = Math.round((glyph.advanceWidth * EM) / font.unitsPerEm);
    const { commands } = glyph.getPath(0, 0, EM);
    const outline = pathData(commands);
    glyphs[char] = outline ? [advance, outline] : [advance];
  }
  const body = JSON.stringify(glyphs);
  const source = `// Generated by scripts/build-glyphs.mjs from @fontsource/${spec.pkg} (SIL OFL 1.1). Do not edit.\nexport default ${body};\n`;
  writeFileSync(join(outDir, `${spec.id}.js`), source);
  console.log(`${spec.id}: ${Object.keys(glyphs).length} glyphs, ${(source.length / 1024).toFixed(1)} KB${missing.length ? `, missing: ${missing.join('')}` : ''}`);
}
